/// <summary>
/// 
/// </summary>
/// <param name = "_nettingPair"></param>
/// <param name = "_currencyCode"></param>
/// <param name = "_sequence"></param>
/// <param name = "_isCreditDebitNote"></param>
/// <param name = "_parameter"></param>
/// <returns></returns>
public Query buildQueryForDebit(CustVendNettingPair _nettingPair, CurrencyCode _currencyCode, CustVendNettingRuleNettingSequence _sequence, boolean _isCreditDebitNote, NettingRuleProcessParameter _parameter)
{
    Query query = next buildQueryForDebit(_nettingPair, _currencyCode, _sequence, _isCreditDebitNote, _parameter);

    if (_sequence == CustVendNettingRuleNettingSequence::METByInvoiceNumber)
    {
        TableId debitTable  = CustVendNettingRuleQueryBuilder::getDataSourceTableId(_nettingPair.DebitAccountType);
        TableId creditTable = CustVendNettingRuleQueryBuilder::getDataSourceTableId(_nettingPair.CreditAccountType);

        QueryBuildDataSource qbdsDebit  = query.dataSourceNo(1);
        QueryBuildDataSource qbdsCredit = qbdsDebit.addDataSource(creditTable);

        qbdsCredit.relations(false);
        qbdsCredit.joinMode(JoinMode::ExistsJoin);

        qbdsCredit.addLink(
            fieldName2Id(debitTable, 'Invoice'),
            fieldName2Id(creditTable, 'Invoice'));

        qbdsCredit.addRange(fieldName2Id(creditTable, 'AccountNum')).value(queryValue(_nettingPair.CreditAccountNum));
    }

    return query;
}

/// <summary>
/// 
/// </summary>
/// <param name = "_nettingPair"></param>
/// <param name = "_currencyCode"></param>
/// <param name = "_sequence"></param>
/// <param name = "_isCreditDebitNote"></param>
/// <param name = "_parameter"></param>
/// <returns></returns>
public Query buildQueryForCredit(CustVendNettingPair _nettingPair, CurrencyCode _currencyCode, CustVendNettingRuleNettingSequence _sequence, boolean _isCreditDebitNote, NettingRuleProcessParameter _parameter)
{
    Query query = next buildQueryForCredit(_nettingPair, _currencyCode, _sequence, _isCreditDebitNote, _parameter);

    if (_sequence == CustVendNettingRuleNettingSequence::METByInvoiceNumber)
    {
        TableId creditTable = CustVendNettingRuleQueryBuilder::getDataSourceTableId(_nettingPair.CreditAccountType);
        TableId debitTable  = CustVendNettingRuleQueryBuilder::getDataSourceTableId(_nettingPair.DebitAccountType);

        QueryBuildDataSource qbdsCredit = query.dataSourceNo(1);
        QueryBuildDataSource qbdsDebit  = qbdsCredit.addDataSource(debitTable);

        qbdsDebit.relations(false);
        qbdsDebit.joinMode(JoinMode::ExistsJoin);

        qbdsDebit.addLink(
        fieldName2Id(creditTable, 'Invoice'),
        fieldName2Id(debitTable, 'Invoice'));

        qbdsDebit.addRange(fieldName2Id(debitTable, 'AccountNum')).value(queryValue(_nettingPair.DebitAccountNum));
    }

    return query;
}

public void applySequence(QueryBuildDataSource _qbds, TableId _dataSourceTableId, CustVendNettingRuleNettingSequence _sequence, boolean _isAmountPositive)
{
    next applySequence(_qbds, _dataSourceTableId, _sequence, _isAmountPositive);

    if (_sequence == CustVendNettingRuleNettingSequence::METByInvoiceNumber)
    {
        // Sort by InvoiceId ascending for Metcash custom sequence
        _qbds.addOrderByField(fieldName2Id(_dataSourceTableId, 'InvoiceId'));
    }
}
